 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not cells:
        return out
    top = min(r for r, c in cells)
    bottom = max(r for r, c in cells)
    left = min(c for r, c in cells)
    right = max(c for r, c in cells)

    # Project the rectangle horizontally through its rows, away from any
    # marker lying outside the rectangle on that row.
    for r in range(top, bottom + 1):
        left_mark = any(grid[r][c] not in (0, 2) for c in range(left))
        right_mark = any(grid[r][c] not in (0, 2) for c in range(right + 1, w))
        if left_mark and not right_mark:
            ranges = [(right + 1, w)]
        elif right_mark and not left_mark:
            ranges = [(0, left)]
        else:
            ranges = [(0, left), (right + 1, w)]
        for a, b in ranges:
            for c in range(a, b):
                if grid[r][c] == 0:
                    out[r][c] = 2

    # Project vertically above and below the rectangle, except on columns
    # occupied by markers in that exterior region.
    for c in range(left, right + 1):
        if not any(grid[r][c] not in (0, 2) for r in range(top)):
            for r in range(top):
                if grid[r][c] == 0:
                    out[r][c] = 2
        if not any(grid[r][c] not in (0, 2) for r in range(bottom + 1, h)):
            for r in range(bottom + 1, h):
                if grid[r][c] == 0:
                    out[r][c] = 2
    return out
